using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Threading;using System.Windows;using System.Windows.Controls;
namespace Iris {
    public sealed class ObsFixture : IObsTransport {
        readonly Queue<Dictionary<string,object>> replies=new Queue<Dictionary<string,object>>();public readonly List<string> Calls=new List<string>();bool active,muted,shown=true;public bool Reject;
        public ObsFixture(){replies.Enqueue(IntegrationJson.Parse("{\"op\":0,\"d\":{\"rpcVersion\":1,\"authentication\":{\"salt\":\"salt\",\"challenge\":\"challenge\"}}}"));}
        public void Send(object message,CancellationToken token){token.ThrowIfCancellationRequested();var map=IntegrationJson.Parse(IntegrationJson.Stringify(message));int op=(int)IntegrationJson.Number(map,"op");var data=IntegrationJson.Get(map,"d");if(op==1){Calls.Add("identify");replies.Enqueue(IntegrationJson.Parse("{\"op\":2,\"d\":{}}"));return;}string type=IntegrationJson.Text(data,"requestType");Calls.Add(type);var payload=new Dictionary<string,object>();if(type=="StartRecord")active=true;if(type=="StopRecord")active=false;if(type=="SetInputMute")muted=IntegrationJson.Bool(IntegrationJson.Get(data,"requestData"),"inputMuted");if(type=="SetSceneItemEnabled")shown=IntegrationJson.Bool(IntegrationJson.Get(data,"requestData"),"sceneItemEnabled");if(type=="GetRecordStatus"||type=="GetStreamStatus")payload["outputActive"]=active;if(type=="GetInputMute")payload["inputMuted"]=muted;if(type=="GetSceneItemId")payload["sceneItemId"]=7;if(type=="GetSceneItemEnabled")payload["sceneItemEnabled"]=shown;replies.Enqueue(IntegrationJson.Parse(IntegrationJson.Stringify(new{op=7,d=new{requestId=IntegrationJson.Text(data,"requestId"),requestStatus=new{result=!Reject,code=Reject?500:100,comment=Reject?"fixture failure":""},responseData=payload}})));}
        public Dictionary<string,object> Receive(CancellationToken token){token.ThrowIfCancellationRequested();return replies.Dequeue();}public void Dispose(){}
    }
    public sealed class SpotifyFixture : ISpotifyApi {
        public readonly List<string> Calls=new List<string>();bool shuffle;string repeat="off";
        public Dictionary<string,object> Request(string method,string path,object body,CancellationToken token){token.ThrowIfCancellationRequested();Calls.Add(method+" "+path+" "+IntegrationJson.Stringify(body));if(path.StartsWith("/me/player/shuffle"))shuffle=path.EndsWith("true");if(path.StartsWith("/me/player/repeat"))repeat=path.Split('=')[1];return IntegrationJson.Parse(IntegrationJson.Stringify(new{shuffle_state=shuffle,repeat_state=repeat,item=new{uri="spotify:track:0123456789012345678901",name="Fixture song"},devices=new[]{new{id="fixture-id",name="Fixture device",type="Computer",is_active=true}}}));}
    }
    public static class AddonPhase4Qa {
        static void Need(bool value,string message){if(!value)throw new Exception(message);}
        public static void Run(string directory){Directory.CreateDirectory(directory);var log=new List<string>();try{
            DownloadCoreQa.Verify(log);Need(AddonCatalog.Builtins().Count()==12,"Module count");Need(AddonRegistry.Definitions.Select(d=>d.Kind).Distinct().Count()==AddonRegistry.Definitions.Count(),"Duplicate kinds");foreach(var package in AddonCatalog.Builtins())Need(AddonCatalog.CheckPackage(package)==null,"Invalid package "+package.Id);
            Need(ProviderMedia.Matches("AppleInc.AppleMusicWin_test!App","applemusic")&&!ProviderMedia.Matches("Spotify.exe","applemusic")&&!ProviderMedia.Matches("malicious-Spotify.exe","spotify"),"Media provider separation");
            Need(SpotifyApi.Challenge("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk")=="E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM","PKCE RFC vector");
            using(var fixture=new ObsFixture()){var obs=new ObsConnection(fixture,"fixture-password",CancellationToken.None);Need(obs.Execute(new AddonAction{Kind="obs-record-start"},CancellationToken.None).ObservedState=="aktiv","OBS start/readback");Need(obs.Execute(new AddonAction{Kind="obs-input-mute",Target="Fixture mic"},CancellationToken.None).ObservedState=="muted","OBS mute/readback");Need(obs.Execute(new AddonAction{Kind="obs-source",Target="Scene | Camera"},CancellationToken.None).ObservedState=="ausgeblendet","OBS source/readback");fixture.Reject=true;bool rejected=false;try{obs.Execute(new AddonAction{Kind="obs-record-stop"},CancellationToken.None);}catch(InvalidOperationException){rejected=true;}Need(rejected,"OBS rejected request claimed success");}
            var spotify=new SpotifyFixture();SpotifyActions.Execute(spotify,new AddonAction{Kind="spotify-api-shuffle"},CancellationToken.None);SpotifyActions.Execute(spotify,new AddonAction{Kind="spotify-api-repeat"},CancellationToken.None);SpotifyActions.Execute(spotify,new AddonAction{Kind="spotify-like"},CancellationToken.None);Need(spotify.Calls.Any(c=>c.StartsWith("PUT /me/library?uris=spotify%3Atrack%3A")),"Deprecated Spotify library route");Need(spotify.Calls.Any(c=>c.Contains("shuffle?state=true"))&&spotify.Calls.Any(c=>c.Contains("repeat?state=context")),"Spotify state transitions");
            var invalid=AddonRegistry.Find("applemusic-playlist").Template();invalid.Target="https://music.apple.com.evil.test/playlist/x";Need(AddonCatalog.Check(invalid,true)!=null,"Playlist host spoof");invalid=AddonRegistry.Find("productivity-timer-start").Template();invalid.Target="1000";Need(AddonCatalog.Check(invalid,true)!=null,"Timer duration mismatch");
            string safe=Path.Combine(directory,"phase4-secret-fixture");AddonConnectionStore.Update(safe,c=>{c.ObsPassword="QA_SECRET_SENTINEL";c.SpotifyClientId=new string('a',32);});Need(!System.Text.Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(safe,"integrations.protected"))).Contains("QA_SECRET_SENTINEL"),"Plaintext secret stored");Need(AddonConnectionStore.Read(safe).ObsPassword=="QA_SECRET_SENTINEL","DPAPI roundtrip");bool denied=false;try{AddonConnectionStore.Update(safe,c=>c.ObsEndpoint="ws://remote.example:4455");}catch(InvalidDataException){denied=true;}Need(denied&&AddonConnectionStore.Read(safe).ObsEndpoint=="ws://127.0.0.1:4455","Rejected save corrupted state");
            log.Add("PASS: 12 modules; unique definitions; manifests; Apple Music / Spotify source isolation; RFC PKCE vector; authenticated OBS handshake/request/status/error fixtures; Spotify state/readback and current library route; link/duration validation; Windows DPAPI and failed-save preservation.");log.Add("No OBS server, Spotify account, audio command, program, clipboard, microphone or UAC used. All transport answers are fixtures.");log.Add("ALL PHASE 4 CORE CHECKS PASSED");
        }catch(Exception ex){Environment.ExitCode=1;log.Add("FAILED: "+ex);}File.WriteAllLines(Path.Combine(directory,"phase4-core-test.txt"),log);}
    }
