            results.Add("PASS: Eight phase4 tiles, quickbar hit targets, 12-module library and connections page rendered in native WPF. Media/OBS/hardware/coding/timer actions use the recording host, not native execution.");VerifyDownloadUi(results);results.Add("ALL PHASE 4 UI CHECKS PASSED");
        }catch(Exception ex){Environment.ExitCode=1;results.Add("FAILED: "+ex);}finally{if(addonWindow!=null)CloseAddonWindow();addonDeck=previous;File.WriteAllLines(Path.Combine(root,"phase4-ui-test.txt"),results);Close();}}
    }
